(@user_jevrem_bjelopavlic, @clinic_id, NULL, 'google_maps',
    'places/ChIJ1VxH0hTrTRMRyy8OYWPH7kU/reviews/Ci9DQUlRQUNvZENodHljRjlvT2twSWRVaEJkRXBSUnpjd01EQXlMVFZLVDNsRVNtYxAB',
